1→import { createHash } from 'node:crypto';
2→import { execFile } from 'node:child_process';
3→import { existsSync, mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, statSync, writeFileSync } from 'node:fs';
4→import { tmpdir } from 'node:os';
5→import { basename, dirname, extname, isAbsolute, join, relative, resolve } from 'node:path';
6→import { pathToFileURL } from 'node:url';
7→import { promisify } from 'node:util';
8→
9→const runFile = promisify(execFile);
10→const sha = (value) => createHash('sha256').update(value).digest('hex');
11→const typed = (message, code, fields = {}) => Object.assign(new Error(message), { code, ...fields });
12→const abort = (ctx) => { if (ctx?.signal?.aborted) throw typed('behavior observation cancelled', 'cancelled'); };
13→const stable = (value) => {
14→  if (Array.isArray(value)) return `[${value.map(stable).join(',')}]`;
15→  if (value && typeof value === 'object') return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stable(value[key])}`).join(',')}}`;
16→  return JSON.stringify(value);
17→};
18→const RUNNER = String.raw`
19→const [targetUrl, exportName, encoded] = process.argv.slice(1);
20→const emit = process.stdout.write.bind(process.stdout);
21→const stringify = JSON.stringify.bind(JSON);
22→const corpus = JSON.parse(Buffer.from(encoded, 'base64').toString('utf8'));
23→const module = await import(targetUrl);
24→const fn = module[exportName];
25→if (typeof fn !== 'function') throw Object.assign(new Error('named export is not a function'), { code: 'EXPORT_NOT_FUNCTION' });
26→const observations = [];
27→for (let caseIndex = 0; caseIndex < corpus.length; caseIndex += 1) {
28→  try {
29→    const value = await fn(corpus[caseIndex]);
30→    if (value === undefined) observations.push({ caseIndex, kind: 'return', valueType: 'undefined' });
31→    else observations.push({ caseIndex, kind: 'return', value: JSON.parse(stringify(value)) });
32→  } catch (error) {
33→    observations.push({ caseIndex, kind: 'throw', name: String(error?.name ?? 'Error'), message: String(error?.message ?? error), code: error?.code ?? null });
34→  }
35→}
36→emit('\nBATON_BEHAVIOR_RESULT:' + stringify(observations) + '\n');
37→`;
38→
39→function bounded(items, tokens) {
40→  const out = [];
41→  for (const item of items) {
42→    if (Buffer.byteLength(JSON.stringify([...out, item])) > tokens * 4) break;
43→    out.push(item);
44→  }
45→  return out;
46→}
47→
48→function validatePath(path) {
49→  if (typeof path !== 'string' || path.length === 0 || isAbsolute(path) || path.split(/[\\/]+/).includes('..')) throw typed('behavior target path escapes root', 'path_escape');
50→  if (!['.js', '.mjs'].includes(extname(path).toLowerCase())) throw typed('behavior fingerprint supports dependency-free JavaScript ESM only', 'unsupported_language');
51→  return path;
52→}
53→
54→function target(root, path, maxSourceBytes) {
55→  if (typeof root !== 'string' || root.length === 0) throw new TypeError('behavior root required');
56→  const realRoot = realpathSync(root); let realTarget;
57→  try { realTarget = realpathSync(resolve(realRoot, validatePath(path))); }
58→  catch (error) { if (error?.code === 'path_escape' || error?.code === 'unsupported_language') throw error; throw typed('behavior target unavailable', 'target_unavailable'); }
59→  const rel = relative(realRoot, realTarget);
60→  if (rel === '' || rel === '..' || rel.startsWith(`..${process.platform === 'win32' ? '\\' : '/'}`) || isAbsolute(rel)) throw typed('behavior target escapes root', 'path_escape');
61→  if (!statSync(realTarget).isFile()) throw typed('behavior target must be a file', 'target_unavailable');
62→  const source = readFileSync(realTarget); if (source.byteLength > maxSourceBytes) throw typed('behavior source exceeds deployment budget', 'source_too_large');
63→  return { realTarget, source, sourceDigest: sha(source) };
64→}
65→
66→function corpusBytes(corpus, maxCorpusCases, maxInputBytes) {
67→  if (!Array.isArray(corpus)) throw new TypeError('behavior corpus must be an array');
68→  if (corpus.length === 0 || corpus.length > maxCorpusCases) throw typed('behavior corpus exceeds deployment case budget', 'corpus_too_large');
69→  let serialized;
70→  try { serialized = JSON.stringify(corpus); } catch { throw typed('behavior corpus must be JSON serializable', 'invalid_corpus'); }
71→  if (serialized === undefined || Buffer.byteLength(serialized) > maxInputBytes) throw typed('behavior corpus exceeds deployment byte budget', 'corpus_too_large');
72→  return { serialized, digest: sha(serialized) };
73→}
74→
75→export class AtlasBehaviorFingerprint {
76→  constructor(opts = {}) {
77→    if (!opts.artifactRoot) throw new TypeError('behavior artifactRoot required');
78→    for (const key of ['maxSourceBytes', 'maxCorpusCases', 'maxInputBytes', 'maxOutputBytes', 'maxArtifactBytes', 'timeoutMs']) {
79→      if (!Number.isSafeInteger(opts[key]) || opts[key] <= 0) throw new TypeError(`${key} must be deployment-derived`);
80→    }
81→    this.artifactRoot = opts.artifactRoot;
82→    this.maxSourceBytes = opts.maxSourceBytes;
83→    this.maxCorpusCases = opts.maxCorpusCases;
84→    this.maxInputBytes = opts.maxInputBytes;
85→    this.maxOutputBytes = opts.maxOutputBytes;
86→    this.maxArtifactBytes = opts.maxArtifactBytes;
87→    this.timeoutMs = opts.timeoutMs;
88→    this.nodePath = opts.nodePath ?? process.execPath;
89→    this.now = opts.now ?? Date.now;
90→    this.record = opts.record ?? null;
91→    mkdirSync(this.artifactRoot, { recursive: true, mode: 0o700 });
92→  }
93→
94→  card() {
95→    return Object.freeze({
96→      name: 'atlas-behavior-fingerprint', version: '0.1.0', underlying: [`node-permission-model@${process.version}`],
97→      ops: {
98→        'behavior.fingerprint': { deterministic: true, latency_class: 'bounded_batch', side_effects: 'executes_target_in_throwaway_permission_sandbox', reverifiable: true },
99→        'behavior.compare': { deterministic: true, latency_class: 'bounded_batch', side_effects: 'executes_targets_in_throwaway_permission_sandboxes', reverifiable: true },
100→      },
101→      limitations: ['dependency-free JavaScript ESM named exports only', 'pinned-corpus observation is not semantic equivalence', 'no input generation or coverage claim', 'filesystem writes, network, child processes, and workers denied'],
102→    });
103→  }
104→
105→  async _once(source, exportName, corpus, ctx) {
106→    abort(ctx);
107→    // macOS exposes its temp root through /var -> /private/var. Node's permission resolver uses
108→    // canonical paths, so grant the canonical sandbox rather than the lexical symlink path.
109→    const sandbox = realpathSync(mkdtempSync(join(tmpdir(), 'baton-behavior-sandbox-')));
110→    const targetPath = join(sandbox, 'target.mjs'); writeFileSync(targetPath, source, { mode: 0o400 });
111→    try {
112→      const encoded = Buffer.from(corpus).toString('base64');
113→      const { stdout } = await runFile(this.nodePath, [
114→        '--permission', `--allow-fs-read=${sandbox}`, '--input-type=module', '-e', RUNNER,
115→        pathToFileURL(targetPath).href, exportName, encoded,
116→      ], {
117→        encoding: 'utf8', timeout: this.timeoutMs, maxBuffer: this.maxOutputBytes, signal: ctx?.signal,
118→        env: { LANG: 'C', LC_ALL: 'C', TZ: 'UTC', NODE_NO_WARNINGS: '1' },
119→      });
120→      const frame = stdout.split('\n').filter((line) => line.startsWith('BATON_BEHAVIOR_RESULT:')).at(-1);
121→      if (!frame) throw typed('behavior child produced no result frame', 'execution_failed');
122→      const observations = JSON.parse(frame.slice('BATON_BEHAVIOR_RESULT:'.length));
123→      if (Buffer.byteLength(JSON.stringify(observations)) > this.maxOutputBytes) throw typed('behavior observations exceed deployment budget', 'output_too_large');
124→      if (observations.some((item) => item.kind === 'throw' && item.code === 'ERR_ACCESS_DENIED')) throw typed('target attempted an operation denied by the permission sandbox', 'sandbox_violation');
125→      return observations;
126→    } catch (error) {
127→      if (error?.code === 'sandbox_violation' || error?.code === 'output_too_large' || error?.code === 'execution_failed') throw error;
128→      if (error?.name === 'AbortError' || error?.code === 'ABORT_ERR') throw typed('behavior observation cancelled', 'cancelled');
129→      if (error?.killed || error?.signal || error?.code === 'ETIMEDOUT') throw typed('behavior observation exceeded execution deadline', 'execution_timeout');
130→      throw typed(`behavior child failed: ${error?.message ?? error}`, error?.message?.includes('EXPORT_NOT_FUNCTION') ? 'invalid_export' : 'execution_failed');
131→    } finally {
132→      rmSync(sandbox, { recursive: true, force: true });
133→    }
134→  }
135→
136→  async _observe(root, path, exportName, corpus, ctx) {
137→    if (typeof exportName !== 'string' || !/^[A-Za-z_$][\w$]*$/.test(exportName)) throw typed('valid named export required', 'invalid_export');
138→    const resolved = target(root, path, this.maxSourceBytes); const input = corpusBytes(corpus, this.maxCorpusCases, this.maxInputBytes);
139→    const first = await this._once(resolved.source, exportName, input.serialized, ctx); abort(ctx);
140→    const second = await this._once(resolved.source, exportName, input.serialized, ctx);
141→    if (stable(first) !== stable(second)) throw typed('target observations differ across isolated repetitions', 'nondeterministic');
142→    return {
143→      path, exportName, sourceDigest: resolved.sourceDigest, corpusDigest: input.digest, observations: first,
144→      nodeVersion: process.version,
145→      sandbox: { permissionModel: true, fsRead: 'isolated_target_only', fsWrite: 'denied', network: 'denied', childProcess: 'denied', workers: 'denied' },
146→    };
147→  }
148→
149→  _writeResult(op, artifact, items, ctx, started) {
150→    const serialized = `${JSON.stringify(artifact)}\n`; const digest = sha(serialized);
151→    if (Buffer.byteLength(serialized) > this.maxArtifactBytes) throw typed('behavior artifact exceeds deployment budget', 'artifact_too_large');
152→    const path = join(this.artifactRoot, `${digest}.json`);
153→    if (existsSync(path) && sha(readFileSync(path)) !== digest) throw typed('behavior artifact integrity failure', 'artifact_integrity');
154→    if (!existsSync(path)) writeFileSync(path, serialized, { mode: 0o600, flag: 'wx' });
155→    const payload = bounded(items, ctx.budgetTokens); const truncated = payload.length < items.length;
156→    const kind = op === 'behavior.fingerprint' ? 'behavior_fingerprint' : 'behavior_comparison';
157→    const meaning = op === 'behavior.fingerprint' ? 'observed_pinned_corpus_not_semantic_equivalence' : 'observed_corpus_agreement_not_semantic_equivalence';
158→    const result = Object.freeze({
159→      op, status: truncated ? 'needs_resume' : 'ok', summary: op === 'behavior.fingerprint' ? `observed ${artifact.observations.length} pinned cases` : `${artifact.divergences.length} observed divergences`, payload,
160→      refs: [{ handle: `art:sha256:${digest}`, kind, digest, bytes: Buffer.byteLength(serialized), mediaType: `application/vnd.baton.atlas-${kind.replaceAll('_', '-')}+json`, path }],
161→      ...(truncated ? { cursor: `atlas-behavior:${digest}:${payload.length}` } : {}),
162→      cost: { tokens_out: Math.ceil(Buffer.byteLength(JSON.stringify(payload)) / 4), wall_ms: Math.max(0, this.now() - started), usd: 0, underlying: `node-permission-model@${process.version}` },
163→      provenance: { artifactDigest: digest, sourceDigests: artifact.sourceDigests ?? [artifact.sourceDigest], corpusDigest: artifact.corpusDigest, exportName: artifact.exportName, nodeVersion: process.version, sandbox: artifact.sandbox, deterministic: true, meaning },
164→    });
165→    this.record?.({ kind: 'capability.op.completed', actor: ctx.actor ?? 'orchestrator', op, digest, status: result.status });
166→    return result;
167→  }
168→
169→  async invoke(op, args, ctx) {
170→    if (!ctx || !Number.isSafeInteger(ctx.budgetTokens) || ctx.budgetTokens <= 0) throw new TypeError('positive budgetTokens required');
171→    if (!['behavior.fingerprint', 'behavior.compare'].includes(op)) throw typed(`unsupported behavior operation: ${op}`, 'unsupported_op');
172→    abort(ctx); const started = this.now(); this.record?.({ kind: 'capability.op.started', actor: ctx.actor ?? 'orchestrator', op });
173→    if (op === 'behavior.fingerprint') {
174→      const observed = await this._observe(ctx.root, validatePath(args?.path), args?.exportName, args?.corpus, ctx);
175→      const artifact = { schemaVersion: 1, op, ...observed };
176→      return this._writeResult(op, artifact, observed.observations, ctx, started);
177→    }
178→    const before = await this._observe(ctx.beforeRoot, validatePath(args?.beforePath), args?.exportName, args?.corpus, ctx); abort(ctx);
179→    const after = await this._observe(ctx.afterRoot, validatePath(args?.afterPath), args?.exportName, args?.corpus, ctx);
180→    const divergences = [];
181→    for (let caseIndex = 0; caseIndex < before.observations.length; caseIndex += 1) {
182→      if (stable(before.observations[caseIndex]) !== stable(after.observations[caseIndex])) divergences.push({ caseIndex, before: before.observations[caseIndex], after: after.observations[caseIndex] });
183→    }
184→    const comparison = { recordType: 'behavior_comparison', agree: divergences.length === 0, cases: before.observations.length, divergences };
185→    const artifact = {
186→      schemaVersion: 1, op, exportName: args.exportName, corpusDigest: before.corpusDigest,
187→      sourceDigests: [before.sourceDigest, after.sourceDigest], before: { path: before.path, observations: before.observations }, after: { path: after.path, observations: after.observations },
188→      sandbox: before.sandbox, divergences,
189→    };
190→    return this._writeResult(op, artifact, [comparison], ctx, started);
191→  }
192→
193→  async resume(ref, cursor, ctx) {
194→    if (!ctx || !Number.isSafeInteger(ctx.budgetTokens) || ctx.budgetTokens <= 0) throw new TypeError('positive budgetTokens required'); abort(ctx);
195→    const match = /^atlas-behavior:([a-f0-9]{64}):(\d+)$/.exec(cursor ?? ''); if (!match || match[1] !== ref?.digest) throw typed('invalid behavior cursor', 'invalid_cursor');
196→    let path; try { path = realpathSync(ref.path); } catch { throw typed('behavior artifact unavailable', 'artifact_integrity'); }
197→    const root = realpathSync(this.artifactRoot); if (path !== join(root, `${ref.digest}.json`)) throw typed('behavior artifact path escape', 'artifact_integrity');
198→    const bytes = readFileSync(path); if (sha(bytes) !== ref.digest) throw typed('behavior artifact digest mismatch', 'artifact_integrity');
199→    let artifact; try { artifact = JSON.parse(bytes); } catch { throw typed('behavior artifact JSON invalid', 'artifact_integrity'); }
200→    if (artifact.schemaVersion !== 1 || !['behavior.fingerprint', 'behavior.compare'].includes(artifact.op)) throw typed('behavior artifact schema mismatch', 'artifact_integrity');
201→    const items = artifact.op === 'behavior.fingerprint' ? artifact.observations : [{ recordType: 'behavior_comparison', agree: artifact.divergences.length === 0, cases: artifact.before.observations.length, divergences: artifact.divergences }];
202→    const offset = Number(match[2]); if (!Number.isSafeInteger(offset) || offset < 0 || offset > items.length) throw typed('invalid behavior cursor offset', 'invalid_cursor');
203→    const payload = bounded(items.slice(offset), ctx.budgetTokens); const next = offset + payload.length; const truncated = next < items.length;
204→    return Object.freeze({ op: artifact.op, status: truncated ? 'needs_resume' : 'ok', summary: `resumed ${payload.length} behavior records`, payload, refs: [ref], ...(truncated ? { cursor: `atlas-behavior:${ref.digest}:${next}` } : {}), cost: { tokens_out: Math.ceil(Buffer.byteLength(JSON.stringify(payload)) / 4), wall_ms: 0, usd: 0, underlying: `node-permission-model@${process.version}` }, provenance: { artifactDigest: ref.digest, resumed_from: offset, deterministic: true } });
205→  }
206→
207→  async reverify(claim, args, ctx) {
208→    const rerun = await this.invoke(claim?.op, args, ctx);
209→    return Object.freeze({ ok: rerun.refs[0].digest === claim?.refs?.[0]?.digest, observedDigest: rerun.refs[0].digest });
210→  }
211→}
