1→#!/usr/bin/env node
2→import { execFileSync } from 'node:child_process';
3→import { existsSync, mkdirSync, mkdtempSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
4→import { tmpdir } from 'node:os';
5→import { dirname, join, resolve } from 'node:path';
6→import { fileURLToPath } from 'node:url';
7→import { AtlasBehaviorFingerprint } from '../../../../impl/src/index.mjs';
8→
9→const HERE = dirname(fileURLToPath(import.meta.url));
10→const OUTPUT = resolve(process.env.BATON_EVIDENCE_DIR ?? HERE);
11→const REPO = resolve(process.env.BATON_REPO ?? resolve(HERE, '../../../..'));
12→const root = mkdtempSync(join(tmpdir(), 'baton-behavior-proof-'));
13→const sandboxes = () => new Set(readdirSync(tmpdir()).filter((name) => name.startsWith('baton-behavior-sandbox-')));
14→const beforeSandboxes = sandboxes(); const events = [];
15→const atlas = new AtlasBehaviorFingerprint({ artifactRoot: join(root, 'artifacts'), maxSourceBytes: 64 * 1024, maxCorpusCases: 16, maxInputBytes: 16 * 1024, maxOutputBytes: 64 * 1024, maxArtifactBytes: 128 * 1024, timeoutMs: 1000, record: (event) => events.push(event) });
16→const args = { path: 'impl/src/route-tuple.mjs', exportName: 'routeTupleKey', corpus: [{ harness: 'codex', version: '1' }, { harness: 'grok', version: '2' }] };
17→let fatal = null; let bounded; let resumed; let reverified; let compared;
18→try {
19→  bounded = await atlas.invoke('behavior.fingerprint', args, { root: REPO, budgetTokens: 1, actor: 'orchestrator' });
20→  resumed = await atlas.resume(bounded.refs[0], bounded.cursor, { budgetTokens: 1000 });
21→  reverified = await atlas.reverify(bounded, args, { root: REPO, budgetTokens: 1000, actor: 'policy' });
22→  compared = await atlas.invoke('behavior.compare', { beforePath: args.path, afterPath: args.path, exportName: args.exportName, corpus: args.corpus }, { beforeRoot: REPO, afterRoot: REPO, budgetTokens: 1000, actor: 'orchestrator' });
23→} catch (error) {
24→  fatal = String(error?.stack ?? error);
25→}
26→const afterSandboxes = sandboxes();
27→const checks = {
28→  noHarnessError: fatal === null,
29→  boundedFirstResult: bounded?.status === 'needs_resume' && bounded?.payload?.length === 0,
30→  realBatonExport: resumed?.payload?.length === 2 && resumed.payload.every((item) => item.kind === 'return' && typeof item.value === 'string'),
31→  deterministicReverify: reverified?.ok === true,
32→  selfComparisonAgrees: compared?.payload?.[0]?.agree === true && compared?.payload?.[0]?.divergences?.length === 0,
33→  claimLanguageHonest: bounded?.provenance?.meaning === 'observed_pinned_corpus_not_semantic_equivalence' && compared?.provenance?.meaning === 'observed_corpus_agreement_not_semantic_equivalence',
